SELECT year,COUNT(*) orders,SUM(gross_sales_cents)/100.0 gross_sales,SUM(discount_cents)/100.0 discounts,SUM(refund_cents)/100.0 refunds,SUM(net_revenue_cents)/100.0 net_revenue,SUM(net_cogs_cents)/100.0 net_cogs,SUM(shipping_cents+return_handling_cents)/100.0 fulfillment,SUM(contribution_cents)/100.0 contribution,1.0*SUM(contribution_cents)/SUM(net_revenue_cents) contribution_margin,1.0*SUM(returned_units)/SUM(quantity) unit_return_rate FROM orders GROUP BY year ORDER BY year
